1	// Command govflow is the DAO 治理提案与执行平台 entry point.
2	package main
3	
4	import (
5		"encoding/json"
6		"flag"
7		"fmt"
8		"io"
9		"os"
10		"sort"
11		"strconv"
12		"strings"
13	
14		"github.com/gzhysuiioo/govflow-proposals/govflow"
15	)
16	
17	const versionText = "govflow 0.2.0"
18	
19	func main() {
20		command := "demo"
21		if len(os.Args) > 1 {
22			command = os.Args[1]
23		}
24		args := os.Args[2:]
25		switch command {
26		case "demo":
27			runDemo()
28		case "version":
29			fmt.Println(versionText)
30		case "help", "-h", "--help":
31			usage()
32		case "init":
33			runInit(args)
34		case "register":
35			runRegister(args)
36		case "create-vote":
37			runCreateVote(args)
38		case "vote":
39			runVote(args)
40		case "tally":
41			runTally(args)
42		case "execute":
43			runExecute(args)
44		case "balances":
45			runBalances(args)
46		case "proposal":
47			runProposal(args)
48		case "proposals":
49			runProposals(args)
50		case "receipt":
51			runReceipt(args)
52		case "receipts":
53			runReceipts(args)
54		default:
55			fmt.Fprintf(os.Stderr, "unknown command %q\n", command)
56			usage()
57			os.Exit(2)
58		}
59	}
