325		var support bool
326		switch *choice {
327		case "for":
328			support = true
329		case "against":
330			support = false
331		default:
332			fmt.Fprintf(os.Stderr, "usage error: --choice must be %q or %q\n", "for", "against")
333			os.Exit(2)
